from __future__ import annotations

from abc import ABC, abstractmethod
from typing import Any


class Filter(ABC):
    @abstractmethod
    def should_include(self, item: Any) -> bool:
        pass


class Transformer(ABC):
    @abstractmethod
    def transform(self, item: Any) -> Any:
        pass


class PassThroughFilter(Filter):
    def should_include(self, item: Any) -> bool:
        return True


class PassThroughTransformer(Transformer):
    def transform(self, item: Any) -> Any:
        return item


class DataProcessor:
    def __init__(self, filter_: Filter | None = None, transformer: Transformer | None = None):
        self._filter = filter_ or PassThroughFilter()
        self._transformer = transformer or PassThroughTransformer()

    def process(self, data: list[Any]) -> list[Any]:
        result = []
        for item in data:
            if not self._filter.should_include(item):
                continue
            result.append(self._transformer.transform(item))
        return result


if __name__ == "__main__":
    class PositiveFilter(Filter):
        def should_include(self, item: Any) -> bool:
            return item > 0

    class DoubleTransformer(Transformer):
        def transform(self, item: Any) -> Any:
            return item * 2

    processor = DataProcessor(filter_=PositiveFilter(), transformer=DoubleTransformer())
    print(processor.process([-1, 0, 1, 2, 3]))  # [2, 4, 6]

