from __future__ import annotations

from abc import ABC, abstractmethod
from typing import Any


class Handler(ABC):
    def __init__(self) -> None:
        self._next: Handler | None = None

    def set_next(self, handler: Handler) -> Handler:
        self._next = handler
        return handler

    @abstractmethod
    def handle(self, item: Any) -> Any | None:
        """Process item and pass to next handler. Return None to drop the item."""

    def _pass_to_next(self, item: Any) -> Any | None:
        if self._next is None:
            return item
        return self._next.handle(item)


class FilterHandler(Handler):
    def __init__(self, predicate: Any) -> None:
        super().__init__()
        self._predicate = predicate

    def handle(self, item: Any) -> Any | None:
        if not self._predicate(item):
            return None
        return self._pass_to_next(item)


class TransformHandler(Handler):
    def __init__(self, func: Any) -> None:
        super().__init__()
        self._func = func

    def handle(self, item: Any) -> Any | None:
        transformed = self._func(item)
        return self._pass_to_next(transformed)


class DataProcessor:
    def __init__(self, *handlers: Handler) -> None:
        for i in range(len(handlers) - 1):
            handlers[i].set_next(handlers[i + 1])
        self._head = handlers[0] if handlers else None

    def process(self, data: list[Any]) -> list[Any]:
        if self._head is None:
            return list(data)
        result = []
        for item in data:
            processed = self._head.handle(item)
            if processed is not None:
                result.append(processed)
        return result


if __name__ == "__main__":
    processor = DataProcessor(
        FilterHandler(lambda x: x > 0),
        TransformHandler(lambda x: x * 2),
    )
    print(processor.process([-1, 0, 1, 2, 3]))  # [2, 4, 6]

